// measureWideProbe is the exact wire bits writeWideProbe would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureWideProbe(WideProbe value) => 403;

// type LudicrousState
final class LudicrousState {
  int mode = DriveMode.none;
  final FixedProbe probe = FixedProbe();
  final WideProbe wide = WideProbe();
  final List<UInt128> keys = List.filled(4, UInt128.zero);
  int keysCount = 0;
  bool hasTarget = false;

  // has_target — wire branch; storage holds both sides, a read zeroes the
  // untaken side (SPEC §5)
  UInt128 targetId = UInt128.zero;
}

// ludicrousStateMaxBits is the longest wire path; align pads at worst case (SPEC §6.1).
// ludicrousStateMaxBytes is rounded up to the 8-byte write-buffer granularity.
const int ludicrousStateMaxBits = 1205;
const int ludicrousStateMaxBytes = 152;

// The §5 zero form: all-zero storage; specified defaults live only in
// construction.
void zeroLudicrousState(LudicrousState value) {
  value.mode = 0;
  zeroFixedProbe(value.probe);
  zeroWideProbe(value.wide);
  value.keys.fillRange(0, value.keys.length, UInt128.zero);
  value.keysCount = 0;
  value.hasTarget = false;
  value.targetId = UInt128.zero;
}

// Restore construction defaults in place; buffers and objects are retained.
void initLudicrousState(LudicrousState value) {
  value.mode = 0;
  initFixedProbe(value.probe);
  initWideProbe(value.wide);
  value.keys.fillRange(0, value.keys.length, UInt128.zero);
  value.keysCount = 0;
  value.hasTarget = false;
  value.targetId = UInt128.zero;
}

// writeLudicrousState packs value into view — the trusted writer (contracts asserted,
// compiled out without --enable-asserts). The buffer behind view must hold
// ludicrousStateMaxBytes. Returns the bytes written, or -1 when a count is outside its
