int writeLudicrousState(LudicrousState value, ByteData view) {
  assert(view.lengthInBytes % 8 == 0);
  assert(view.lengthInBytes >= ludicrousStateMaxBytes);
  var scratch = 0;
  var scratchBits = 0;
