  var v = 0;
  assert(value.mode >= 0);
  assert(value.mode <= 3);
  assert(value.probe.angle >= -11796480);
  assert(value.probe.angle <= 11796480);
  assert(value.probe.position >= -1966080000);
  assert(value.probe.position <= 1966080000);
  v =
      ((value.mode) & 0x3) |
      (((value.probe.angle + 11796480) & 0x1ffffff) << 2) |
      (((value.probe.position + 1966080000) & 0xffffffff) << 27);
