  for (var i0 = 0; i0 < 2; i0++) {
    assert(value.probe.samples[i0] >= -524288);
    assert(value.probe.samples[i0] <= 524288);
    v = ((value.probe.samples[i0] + 524288) & 0x1fffff);
    scratch |= v << scratchBits;
    scratchBits += 21;
