  v = (value.wide.seed.lo);
  scratch |= v << scratchBits;
  scratchBits += 64;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (64 - scratchBits);
  }
  if (value.keysCount < 0 || value.keysCount > 4) {
