  scratch |= v << scratchBits;
  scratchBits += 1;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (1 - scratchBits);
  }
