    v = (value.targetId.lo);
    scratch |= v << scratchBits;
    scratchBits += 64;
    if (scratchBits >= 64) {
      view.setUint64(wordIndex * 8, scratch, Endian.little);
      wordIndex++;
      scratchBits -= 64;
      scratch = v >>> (64 - scratchBits);
    }
    v = (value.targetId.hi);
    scratch |= v << scratchBits;
    scratchBits += 64;
    if (scratchBits >= 64) {
      view.setUint64(wordIndex * 8, scratch, Endian.little);
      wordIndex++;
      scratchBits -= 64;
      scratch = v >>> (64 - scratchBits);
    }
  }
  if (scratchBits != 0) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
  }
  return wordIndex * 8 + ((scratchBits + 7) >>> 3);
}

